import{_ as l,c as e,o as r,a3 as i}from"./chunks/framework.BurWKwwG.js";const _=JSON.parse('{"title":"介绍与概述","description":"","frontmatter":{},"headers":[],"relativePath":"zh/1_overview.md","filePath":"zh/1_overview.md"}'),t={name:"zh/1_overview.md"};function s(n,a,o,h,d,g){return r(),e("div",null,a[0]||(a[0]=[i('<h1 id="介绍与概述" tabindex="-1">介绍与概述 <a class="header-anchor" href="#介绍与概述" aria-label="Permalink to “介绍与概述”">​</a></h1><h2 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to “介绍”">​</a></h2><p>CBD3（结直肠癌生物标志物数据库 v3）是一个集成生物标志物、临床数据和单细胞RNA测序数据的综合分析平台，旨在加速结直肠癌研究。</p><h2 id="核心功能" tabindex="-1">核心功能 <a class="header-anchor" href="#核心功能" aria-label="Permalink to “核心功能”">​</a></h2><ul><li><strong>生物标志物浏览</strong>：从精选医学文献中整理并手动验证的结直肠癌生物标志物数据库</li><li><strong>单细胞基因表达图谱</strong>：基于 UMAP 的交互式单细胞基因表达可视化</li><li><strong>蛋白质互作网络</strong>：基于 Cytoscape.js 的 PPI 网络浏览与探索</li><li><strong>综合单细胞分析</strong>： <ul><li>DEGs（差异表达基因）：火山图与分页表格</li><li>KEGG 通路富集分析</li><li>Ridge 排名图</li><li>轨迹分析与伪时间分析</li><li>CellChat 细胞通讯分析</li><li>网络敏感性分析</li><li>ROC 预测能力分析</li></ul></li><li><strong>临床分析</strong>：Kaplan-Meier 生存曲线、免疫浸润热力图</li><li><strong>数据下载与提交</strong>：支持数据导出和社区贡献</li></ul><h2 id="数据来源" tabindex="-1">数据来源 <a class="header-anchor" href="#数据来源" aria-label="Permalink to “数据来源”">​</a></h2><ul><li><strong>PubMed 文献</strong>：手工整理的生物标志物数据</li><li><strong>TCGA</strong>：COAD/READ 临床验证数据与生存数据</li><li><strong>GEO</strong>：单细胞 RNA 测序数据</li><li><strong>STRING</strong>：蛋白质-蛋白质相互作用网络</li><li><strong>DrugBank</strong>：药物与靶点数据</li></ul><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to “技术栈”">​</a></h2><ul><li><strong>前端</strong>：Vue 3 + Vite + Element Plus + ECharts + Cytoscape.js</li><li><strong>后端</strong>：Node.js + Express 5 + MySQL2</li><li><strong>数据库</strong>：MySQL（12 张核心表，约 3640 万行数据）</li><li><strong>包管理</strong>：pnpm</li></ul><h2 id="引用" tabindex="-1">引用 <a class="header-anchor" href="#引用" aria-label="Permalink to “引用”">​</a></h2><p>如果您在研究中使用 CBD3，请引用我们的工作。更多信息请查看<a href="/docs/5_cite.html">引用与支持</a>页面。</p><h2 id="开发者" tabindex="-1">开发者 <a class="header-anchor" href="#开发者" aria-label="Permalink to “开发者”">​</a></h2><p>CBD3 是一个基于 MIT 许可证发布的开源项目。有关贡献指南，请查看<a href="/docs/4_dev.html">开发者指南</a>。</p>',13)]))}const p=l(t,[["render",s]]);export{_ as __pageData,p as default};
